/** Same UI for the standalone importer and the DSH iframe host. */
function renderLocalWorkbenchPageBase({ apiBase = '/api', initialPage = 'new' }: { apiBase?: string; initialPage?: 'new' | 'templates' } = {}): string {
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>看板工作台</title><style>${styles()}${attachmentStyles()}${scaleOverrides()}${interfaceIconStyles()}${cleanHistoryStyles()}${streamStyles()}${streamDetailStyles()}${taskLaunchStyles()}${conversationComposerStyles()}${conversationComposerCompactStyles()}${sendControlStyles()}${heroTitleStyles()}${heroParticleStyles()}${particleMarkStyles()}${templateLibraryStyles()}${templateLibraryResilienceStyles()}${templateCoverCardStyles()}${templateLibraryLinkStyles()}${collapsedSidebarToggleStyles()}${tooltipStyles()}${myDashboardsStyles()}${myDashboardsLiveStyles()}</style></head><body>${shell()}<script>${tooltipBehavior()}</script><script>${behaviorV2()}</script><script>${historyPersistenceBehavior()}</script><script>${sendControlBehavior()}</script><script>${newDashboardResetScript()}</script><script>${heroTitleBehavior()}</script><script>${heroParticleBehaviorV3()}</script><script type="importmap">{"imports":{"three":"/assets/three.module.js"}}</script><script type="module">${particleMarkInteractiveBehavior()}</script><script>${particleMarkFallbackInteractiveBehavior()}</script><script>${myDashboardsBehavior()}</script><script>${libraryHubBehavior()}</script></body></html>`
}

