function heroTitleBehavior(): string {
  return `(()=>{const decorate=()=>{const title=document.querySelector('#page-content .task-launch .chat-empty h1');if(!title||title.parentElement?.classList.contains('hero-title-row'))return;const row=document.createElement('div'),logo=document.createElement('img');row.className='hero-title-row';logo.className='hero-title-logo';logo.src=(location.pathname.startsWith('/dsh-workbench')?'/dsh-workbench':'')+'/'+'assets/data-agent-logo-black.png';logo.alt='';logo.setAttribute('aria-hidden','true');title.before(row);row.append(logo,title)};decorate();new MutationObserver(decorate).observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true})})()`
}

function heroParticleStyles(): string {
  return `.task-launch{position:relative}.hero-particle-canvas{position:absolute;z-index:0;pointer-events:none;inset-inline:0;display:block}.task-launch>.chat-empty,.task-launch>.task-launch-composer{position:relative;z-index:1}.hero-title-logo{cursor:pointer;transition:transform 160ms ease-out}.hero-title-logo:hover{transform:scale(1.05)}.hero-title-logo:focus-visible{outline:1px solid rgba(23,23,23,.45);outline-offset:2px;border-radius:50%}@media(prefers-reduced-motion:reduce){.hero-title-logo{transition:none}.hero-title-logo:hover{transform:none}.hero-title-logo:active{transform:scale(1.03)}.hero-particle-canvas{display:none}}`
}

function heroParticleBehavior(): string {
  return `(()=>{let activeLaunch=null,dispose=()=>{};const motion=matchMedia('(prefers-reduced-motion: reduce)');const random=(min,max)=>min+Math.random()*(max-min);const boot=()=>{const launch=document.querySelector('#page-content .task-launch'),logo=launch?.querySelector('.hero-title-logo'),row=launch?.querySelector('.hero-title-row'),composer=launch?.querySelector('.task-launch-composer');if(!launch||!logo||!row||!composer||launch===activeLaunch)return;dispose();activeLaunch=launch;const canvas=document.createElement('canvas'),context=canvas.getContext('2d'),image=new Image(),mobile=matchMedia('(max-width:760px)').matches,maxParticles=mobile?6:12,particles=[],pool=[];let frame=0,last=0,nextSpawn=0,ready=false,running=false,slowFrames=0,performancePaused=false;canvas.className='hero-particle-canvas';canvas.setAttribute('aria-hidden','true');launch.prepend(canvas);const assetBase=location.pathname.startsWith('/dsh-workbench')?'/dsh-workbench':'';image.src=assetBase+'/'+'assets/data-agent-logo-black.png';const recycle=particle=>{particles.splice(particles.indexOf(particle),1);pool.push(particle)};const sync=()=>{const launchRect=launch.getBoundingClientRect(),rowRect=row.getBoundingClientRect(),composerRect=composer.getBoundingClientRect(),top=Math.max(0,rowRect.top-launchRect.top-80),height=Math.max(1,composerRect.top-launchRect.top-top),width=launchRect.width,dpr=Math.min(window.devicePixelRatio||1,2);canvas.style.top=top+'px';canvas.style.width=width+'px';canvas.style.height=height+'px';canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);context?.setTransform(dpr,0,0,dpr,0,0)};const origin=()=>{const canvasRect=canvas.getBoundingClientRect(),logoRect=logo.getBoundingClientRect();return{x:logoRect.left-canvasRect.left+logoRect.width*.45,y:logoRect.top-canvasRect.top+logoRect.height*.52}};const add=(kind='default')=>{if(!ready||motion.matches||particles.length>=maxParticles)return;const burst=kind==='burst',hover=kind==='hover',base=origin(),angle=burst?random(0,Math.PI*2):hover?random(-2.6,-.55):random(-2.8,-1.4),speed=burst?random(45,90):random(20,55),particle=pool.pop()||{};Object.assign(particle,{x:base.x,y:base.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,size:burst?random(8,14):Math.random()<.2?random(14,18):random(10,14),age:0,life:burst?random(1.2,2):random(2.2,3.8),phase:random(0,Math.PI*2),amplitude:mobile?0:random(8,16),frequency:mobile?0:random(.8,1.4),angle:random(-20,20)*Math.PI/180,spin:random(-18,18)*Math.PI/180,opacity:burst?.22:random(.08,.16),burst});particles.push(particle)};const emit=(count,kind)=>{for(let index=0;index<count;index+=1)add(kind)};const draw=(now,delta)=>{if(!context)return;context.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);for(const particle of [...particles]){particle.age+=delta;if(particle.age>=particle.life||particle.y<-28||particle.x<-28||particle.x>canvas.clientWidth+28){recycle(particle);continue}const progress=particle.age/particle.life,drag=Math.pow(.985,delta*60);particle.vx*=drag;particle.vy*=drag;particle.x+=particle.vx*delta;particle.y+=particle.vy*delta;particle.angle+=particle.spin*delta;const fade=progress<.15?progress/.15:progress>.72?Math.max(0,1-(progress-.72)/.28):1,scale=progress<.14?.65+.35*(progress/.14):progress>.74?1-.2*((progress-.74)/.26):.9+.15*Math.sin(progress*Math.PI),x=particle.x+Math.sin(now*.001*particle.frequency+particle.phase)*particle.amplitude,size=particle.size*scale;context.save();context.globalAlpha=Math.min(particle.opacity*fade,particle.burst?.22:.18);context.translate(x,particle.y);context.rotate(particle.angle);context.drawImage(image,-size/2,-size/2,size,size);context.restore()}};const tick=now=>{if(!running||motion.matches||document.hidden)return;const delta=Math.min(.05,(now-last)/1000||0);last=now;slowFrames=delta>=.045?slowFrames+1:Math.max(0,slowFrames-1);if(slowFrames>60){running=false;return}if(now>=nextSpawn){add();nextSpawn=now+random(700,1100)}draw(now,delta);frame=requestAnimationFrame(tick)};const start=()=>{if(!ready||motion.matches||document.hidden||performancePaused||running)return;running=true;last=performance.now();nextSpawn=last+800;frame=requestAnimationFrame(tick)};const pause=()=>{running=false;cancelAnimationFrame(frame)};const enter=()=>{if(!motion.matches)emit(Math.floor(random(3,6)),'hover')};const click=()=>{if(!motion.matches)emit(Math.floor(random(8,13)),'burst')};const keydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();click()}};const visibility=()=>document.hidden?pause():start();const resize=()=>sync();sync();logo.classList.add('is-interactive');logo.tabIndex=0;logo.setAttribute('role','button');logo.setAttribute('aria-label','播放 Data Agent 图标粒子效果');logo.addEventListener('pointerenter',enter);logo.addEventListener('click',click);logo.addEventListener('keydown',keydown);window.addEventListener('resize',resize,{passive:true});document.addEventListener('visibilitychange',visibility);image.addEventListener('load',()=>{ready=true;setTimeout(start,800)},{once:true});const onMotion=()=>motion.matches?pause():start();motion.addEventListener?.('change',onMotion);dispose=()=>{pause();logo.removeEventListener('pointerenter',enter);logo.removeEventListener('click',click);logo.removeEventListener('keydown',keydown);window.removeEventListener('resize',resize);document.removeEventListener('visibilitychange',visibility);motion.removeEventListener?.('change',onMotion);canvas.remove();activeLaunch=null};};const observer=new MutationObserver(boot);observer.observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true});boot()})()`
}

function heroParticleBehaviorV2(): string {
  return heroParticleBehavior().replace('particle.burst?.22:.18', 'particle.burst ? .22 : .18')
}

function heroParticleBehaviorV3(): string {
  return heroParticleBehaviorV2().replace("logo.classList.add('is-interactive');logo.tabIndex=0", "logo.classList.add('is-interactive');logo.removeAttribute('aria-hidden');logo.tabIndex=0")
}

/** Decorative WebGL background for the empty-state task launcher. It never receives pointer input. */
function particleMarkStyles(): string {
  return `.particle-mark{position:absolute;z-index:0;top:8px;right:-250px;width:min(44vw,700px);height:min(68vh,560px);min-height:420px;overflow:hidden;isolation:isolate;pointer-events:auto;cursor:crosshair;background:transparent}.particle-mark canvas{position:absolute;inset:0;display:block;width:100%;height:100%;pointer-events:none}@media(max-width:1100px){.particle-mark{top:0;right:-120px;width:min(62vw,580px);height:min(64vh,520px)}}@media(max-width:760px){.particle-mark{top:-24px;right:-96px;width:420px;height:460px;min-height:0;opacity:.72}}`
}

function particleMarkBehavior(): string {
  return `import * as THREE from 'three';(()=>{let activeLaunch=null,dispose=()=>{};const motion=matchMedia('(prefers-reduced-motion: reduce)');const angleDistance=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b));const insideMark=(x,y)=>{const radius=Math.hypot(x,y),angle=Math.atan2(y,x),lobes=[{angle:1.18,reach:2.75,width:.31},{angle:-.08,reach:2.65,width:.49},{angle:-2.08,reach:2.54,width:.42},{angle:2.73,reach:2.48,width:.48}];let edge=.72;for(const lobe of lobes){const delta=angleDistance(angle,lobe.angle),contribution=.72+(lobe.reach-.72)*Math.exp(-(delta**2)/(2*lobe.width**2));edge=Math.max(edge,contribution)}if(radius>=edge)return false;const topWing=((x+.22)/.27)**2+((y-.18)/.34)**2<1||((x-.22)/.27)**2+((y-.18)/.34)**2<1,lowerWing=((x+.2)/.25)**2+((y+.22)/.23)**2<1||((x-.2)/.25)**2+((y+.22)/.23)**2<1,body=(x/.105)**2+(y/.32)**2<1;return !(topWing||lowerWing||body)};const mount=()=>{const launch=document.querySelector('#page-content .task-launch');if(!launch||launch===activeLaunch)return;dispose();activeLaunch=launch;const panel=document.createElement('div');panel.className='particle-mark';panel.setAttribute('aria-hidden','true');launch.prepend(panel);let cancelled=false,frame=0,renderer=null,geometry=null,material=null,resizeObserver=null;const stop=()=>cancelAnimationFrame(frame);const onMotion=()=>{if(motion.matches)stop()};const onVisibility=()=>{if(document.hidden)stop()};dispose=()=>{cancelled=true;stop();resizeObserver?.disconnect();document.removeEventListener('visibilitychange',onVisibility);motion.removeEventListener?.('change',onMotion);geometry?.dispose();material?.dispose();renderer?.dispose();renderer?.domElement.remove();panel.remove();activeLaunch=null};try{const mobile=matchMedia('(max-width:760px)').matches,particleCount=mobile?6000:12000,positions=new Float32Array(particleCount*3),targets=new Float32Array(particleCount*2);for(let i=0;i<particleCount;i+=1){let x=0,y=0;do{x=(Math.random()-.5)*5.8;y=(Math.random()-.5)*5.8}while(!insideMark(x,y));const i2=i*2,i3=i*3;targets[i2]=x;targets[i2+1]=y;positions[i3]=motion.matches?x:(Math.random()-.5)*10;positions[i3+1]=motion.matches?y:(Math.random()-.5)*10;positions[i3+2]=motion.matches?0:(Math.random()-.5)*5}geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));material=new THREE.PointsMaterial({color:'#E4BFFF',size:mobile ? .02 : .015,transparent:true,opacity:.6,blending:THREE.AdditiveBlending,depthWrite:false,sizeAttenuation:true});const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(75,1,.1,1000),particles=new THREE.Points(geometry,material);camera.position.z=5;scene.add(particles);renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.setClearColor(0x000000,0);panel.prepend(renderer.domElement);const resize=()=>{if(!renderer||!panel.isConnected)return;const width=Math.max(1,panel.clientWidth),height=Math.max(1,panel.clientHeight);camera.aspect=width/height;camera.updateProjectionMatrix();renderer.setSize(width,height,false)};resizeObserver=new ResizeObserver(resize);resizeObserver.observe(panel);resize();let time=0;const draw=()=>{if(cancelled||!renderer||!geometry)return;time+=.01;const attribute=geometry.attributes.position;for(let i=0;i<particleCount;i+=1){const i2=i*2,i3=i*3,targetX=targets[i2]+Math.sin(time*.65+targets[i2+1]*2.4)*.028,targetY=targets[i2+1]+Math.cos(time*.55+targets[i2]*2.1)*.028,flutter=Math.sin(time*2+i*.01)*.2;positions[i3]+=(targetX-positions[i3])*.02;positions[i3+1]+=(targetY-positions[i3+1])*.02;positions[i3+2]+=(flutter-positions[i3+2])*.01}attribute.needsUpdate=true;particles.rotation.y=Math.sin(time*.5)*.15;particles.rotation.z=Math.cos(time*.3)*.05;camera.position.x=Math.sin(time*.2)*.5;camera.position.y=Math.cos(time*.2)*.5;camera.lookAt(0,0,0);renderer.render(scene,camera);if(!motion.matches&&!document.hidden)frame=requestAnimationFrame(draw)};draw();document.addEventListener('visibilitychange',onVisibility);motion.addEventListener?.('change',onMotion)}catch{dispose()}};const observer=new MutationObserver(mount);observer.observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true});window.addEventListener('pagehide',()=>{observer.disconnect();dispose()},{once:true});mount()})()`
}

/** Makes the existing WebGL mark disperse on click, then naturally reform at its fixed targets. */
function particleMarkInteractiveBehavior(): string {
  return particleMarkBehavior()
    .replace(
      'positions=new Float32Array(particleCount*3),targets=new Float32Array(particleCount*2);',
      'positions=new Float32Array(particleCount*3),targets=new Float32Array(particleCount*2),velocities=new Float32Array(particleCount*3);',
    )
    .replace(
      'let cancelled=false,frame=0,renderer=null,geometry=null,material=null,resizeObserver=null;',
      'let cancelled=false,frame=0,renderer=null,geometry=null,material=null,resizeObserver=null,scatter=null;',
    )
    .replace(
      "motion.removeEventListener?.('change',onMotion);geometry?.dispose();",
      "motion.removeEventListener?.('change',onMotion);panel.removeEventListener('pointerdown',scatter);geometry?.dispose();",
    )
    .replace(
      'camera.position.z=5;scene.add(particles);',
      "camera.position.z=5;scene.add(particles);scatter=event=>{if(motion.matches)return;const rect=panel.getBoundingClientRect(),height=Math.max(1,rect.height),viewHeight=2*Math.tan(camera.fov*Math.PI/360)*camera.position.z,originX=((event.clientX-rect.left)/rect.width-.5)*viewHeight*(rect.width/height),originY=(.5-(event.clientY-rect.top)/rect.height)*viewHeight;for(let i=0;i<particleCount;i+=1){const i3=i*3,dx=positions[i3]-originX+(Math.random()-.5)*.42,dy=positions[i3+1]-originY+(Math.random()-.5)*.42,distance=Math.hypot(dx,dy)||.01,force=.045+Math.random()*.095;velocities[i3]=dx/distance*force;velocities[i3+1]=dy/distance*force;velocities[i3+2]=(Math.random()-.5)*force*.9}};panel.addEventListener('pointerdown',scatter);",
    )
    .replace(
      'positions[i3]+=(targetX-positions[i3])*.02;positions[i3+1]+=(targetY-positions[i3+1])*.02;positions[i3+2]+=(flutter-positions[i3+2])*.01',
      'positions[i3]+=(targetX-positions[i3])*.02+velocities[i3];positions[i3+1]+=(targetY-positions[i3+1])*.02+velocities[i3+1];positions[i3+2]+=(flutter-positions[i3+2])*.01+velocities[i3+2];velocities[i3]*=.88;velocities[i3+1]*=.88;velocities[i3+2]*=.88',
    )
}

/** Kept deliberately visual-only: this path runs only when the current device has no usable WebGL context. */
function particleMarkFallbackBehavior(): string {
  return `(()=>{let activeLaunch=null,dispose=()=>{};const motion=matchMedia('(prefers-reduced-motion: reduce)'),angleDistance=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b)),insideMark=(x,y)=>{const radius=Math.hypot(x,y),angle=Math.atan2(y,x),lobes=[{angle:1.18,reach:2.75,width:.31},{angle:-.08,reach:2.65,width:.49},{angle:-2.08,reach:2.54,width:.42},{angle:2.73,reach:2.48,width:.48}];let edge=.72;for(const lobe of lobes){const delta=angleDistance(angle,lobe.angle);edge=Math.max(edge,.72+(lobe.reach-.72)*Math.exp(-(delta**2)/(2*lobe.width**2)))}if(radius>=edge)return false;const top=((x+.22)/.27)**2+((y-.18)/.34)**2<1||((x-.22)/.27)**2+((y-.18)/.34)**2<1,lower=((x+.2)/.25)**2+((y+.22)/.23)**2<1||((x-.2)/.25)**2+((y+.22)/.23)**2<1,body=(x/.105)**2+(y/.32)**2<1;return !(top||lower||body)};const mount=()=>{const launch=document.querySelector('#page-content .task-launch');if(!launch||launch===activeLaunch||launch.querySelector('.particle-mark'))return;dispose();activeLaunch=launch;const panel=document.createElement('div'),canvas=document.createElement('canvas'),context=canvas.getContext('2d');panel.className='particle-mark';panel.dataset.renderer='canvas-fallback';panel.setAttribute('aria-hidden','true');panel.append(canvas);launch.prepend(panel);const mobile=matchMedia('(max-width:760px)').matches,count=mobile?6000:12000,positions=new Float32Array(count*3),targets=new Float32Array(count*2);for(let i=0;i<count;i+=1){let x=0,y=0;do{x=(Math.random()-.5)*5.8;y=(Math.random()-.5)*5.8}while(!insideMark(x,y));const i2=i*2,i3=i*3;targets[i2]=x;targets[i2+1]=y;positions[i3]=motion.matches?x:(Math.random()-.5)*10;positions[i3+1]=motion.matches?y:(Math.random()-.5)*10;positions[i3+2]=motion.matches?0:(Math.random()-.5)*5}let frame=0,time=0,width=1,height=1,dpr=1;const resize=()=>{width=Math.max(1,panel.clientWidth);height=Math.max(1,panel.clientHeight);dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);context?.setTransform(dpr,0,0,dpr,0,0)};const observer=new ResizeObserver(resize);observer.observe(panel);resize();const draw=()=>{if(!context||!panel.isConnected)return;time+=.01;context.clearRect(0,0,width,height);const scale=Math.min(width,height)/6.15,cosY=Math.cos(Math.sin(time*.5)*.15),sinY=Math.sin(Math.sin(time*.5)*.15),roll=Math.cos(time*.3)*.05,cosR=Math.cos(roll),sinR=Math.sin(roll),driftX=Math.sin(time*.2)*.5,driftY=Math.cos(time*.2)*.5;context.fillStyle='rgba(228,191,255,.6)';for(let i=0;i<count;i+=1){const i2=i*2,i3=i*3,targetX=targets[i2]+Math.sin(time*.65+targets[i2+1]*2.4)*.028,targetY=targets[i2+1]+Math.cos(time*.55+targets[i2]*2.1)*.028,flutter=Math.sin(time*2+i*.01)*.2;positions[i3]+=(targetX-positions[i3])*.02;positions[i3+1]+=(targetY-positions[i3+1])*.02;positions[i3+2]+=(flutter-positions[i3+2])*.01;const yawX=positions[i3]*cosY+positions[i3+2]*sinY,yawY=positions[i3+1],x=yawX*cosR-yawY*sinR,y=xawY=yawX*sinR+yawY*cosR,depth=positions[i3+2],px=width*.5+(x+driftX)*scale,py=height*.5+(y+driftY)*scale,size=Math.max(.55,1.25-depth*.1);context.fillRect(px,py,size,size)}if(!motion.matches&&!document.hidden)frame=requestAnimationFrame(draw)};draw();dispose=()=>{cancelAnimationFrame(frame);observer.disconnect();panel.remove();activeLaunch=null}};const retry=()=>setTimeout(mount,1200);const pageObserver=new MutationObserver(retry);pageObserver.observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true});window.addEventListener('pagehide',()=>{pageObserver.disconnect();dispose()},{once:true});retry()})()`
}

/** Canvas fallback with the same existing-particle scatter physics as the WebGL renderer. */
function particleMarkFallbackInteractiveBehavior(): string {
  return particleMarkFallbackBehavior()
    .replace(
      'positions=new Float32Array(count*3),targets=new Float32Array(count*2);',
      'positions=new Float32Array(count*3),targets=new Float32Array(count*2),velocities=new Float32Array(count*3);',
    )
    .replace(
      'let frame=0,time=0,width=1,height=1,dpr=1;',
      "let frame=0,time=0,width=1,height=1,dpr=1;const scatter=event=>{if(motion.matches)return;const rect=panel.getBoundingClientRect(),scale=Math.min(rect.width,rect.height)/6.15,originX=(event.clientX-rect.left-rect.width*.5)/scale,originY=(event.clientY-rect.top-rect.height*.5)/scale;for(let i=0;i<count;i+=1){const i3=i*3,dx=positions[i3]-originX+(Math.random()-.5)*.42,dy=positions[i3+1]-originY+(Math.random()-.5)*.42,distance=Math.hypot(dx,dy)||.01,force=.045+Math.random()*.095;velocities[i3]=dx/distance*force;velocities[i3+1]=dy/distance*force;velocities[i3+2]=(Math.random()-.5)*force*.9}};panel.addEventListener('pointerdown',scatter);",
    )
    .replace(
      'positions[i3]+=(targetX-positions[i3])*.02;positions[i3+1]+=(targetY-positions[i3+1])*.02;positions[i3+2]+=(flutter-positions[i3+2])*.01',
      'positions[i3]+=(targetX-positions[i3])*.02+velocities[i3];positions[i3+1]+=(targetY-positions[i3+1])*.02+velocities[i3+1];positions[i3+2]+=(flutter-positions[i3+2])*.01+velocities[i3+2];velocities[i3]*=.88;velocities[i3+1]*=.88;velocities[i3+2]*=.88',
    )
    .replace(
      'observer.disconnect();panel.remove();activeLaunch=null',
      "observer.disconnect();panel.removeEventListener('pointerdown',scatter);panel.remove();activeLaunch=null",
    )
}

/** A short-lived particle-ring overlay lets the otherwise decorative mark respond to clicks. */
function particleMarkRippleBehavior(): string {
  return `(()=>{let active=null,dispose=()=>{};const mount=()=>{const panel=document.querySelector('#page-content .particle-mark');if(!panel||panel===active)return;dispose();active=panel;const canvas=document.createElement('canvas'),context=canvas.getContext('2d'),waves=[];canvas.className='particle-ripple-canvas';canvas.setAttribute('aria-hidden','true');panel.append(canvas);let width=1,height=1,dpr=1,frame=0;const resize=()=>{width=Math.max(1,panel.clientWidth);height=Math.max(1,panel.clientHeight);dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);context?.setTransform(dpr,0,0,dpr,0,0)};const observer=new ResizeObserver(resize);observer.observe(panel);resize();const ripple=event=>{const rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;for(let ring=0;ring<3;ring+=1){for(let index=0;index<74;index+=1){const angle=(index/74)*Math.PI*2+Math.random()*.08;waves.push({x,y,angle,delay:ring*75+Math.random()*26,speed:92+ring*24+Math.random()*36,created:performance.now(),jitter:Math.random()*8})}}};const draw=now=>{if(!context||!panel.isConnected)return;context.clearRect(0,0,width,height);for(let index=waves.length-1;index>=0;index-=1){const wave=waves[index],age=now-wave.created-wave.delay;if(age<0)continue;if(age>940){waves.splice(index,1);continue}const progress=age/940,radius=wave.speed*(age/1000),fade=(1-progress)**1.7,offset=Math.sin(progress*11+wave.jitter)*3*(1-progress),x=wave.x+Math.cos(wave.angle)*(radius+offset),y=wave.y+Math.sin(wave.angle)*(radius+offset);context.fillStyle='rgba(228,191,255,'+(fade*.72)+')';context.fillRect(x,y,1.5-fade*.5,1.5-fade*.5)}frame=requestAnimationFrame(draw)};panel.addEventListener('pointerdown',ripple);frame=requestAnimationFrame(draw);dispose=()=>{cancelAnimationFrame(frame);observer.disconnect();panel.removeEventListener('pointerdown',ripple);canvas.remove();active=null}};const observer=new MutationObserver(mount);observer.observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true});window.addEventListener('pagehide',()=>{observer.disconnect();dispose()},{once:true});mount()})()`
}

