/** Starts a clean workbench state when the sidebar creates another dashboard. */
function newDashboardResetScript(): string {
  return `(()=>{const sidebarStateKey='dsh-workbench:sidebar-collapsed',sidebar=document.querySelector('.sidebar');const applySidebarState=collapsed=>{sidebar?.classList.toggle('collapsed',collapsed);const button=document.getElementById('collapse-button');button?.setAttribute('aria-label',collapsed?'展开侧栏':'收起侧栏');button?.setAttribute('data-tooltip',collapsed?'展开侧栏':'收起侧栏')};const route=page=>{const url=new URL(location.href);url.pathname=page==='templates'?'/dsh-workbench/templates':'/dsh-workbench';history.pushState({},'',url)};applySidebarState(sessionStorage.getItem(sidebarStateKey)==='true');document.addEventListener('click',event=>{const item=event.target instanceof Element?event.target.closest('.nav-item[data-page="new"],.template-nav-item[data-page="templates"]'):null;if(!item)return;const page=item.dataset.page;if(page==='templates'||location.pathname.endsWith('/templates'))route(page)},true);document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('#collapse-button'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();const collapsed=!sidebar?.classList.contains('collapsed');sessionStorage.setItem(sidebarStateKey,String(collapsed));applySidebarState(collapsed)},true)})()`
}

