function sendControlBehavior(): string {
  const playIcon = JSON.stringify(icon('play'))
  const stopIcon = JSON.stringify(icon('stop'))
  return `(()=>{let pauseRequested=false;const playIcon=${playIcon},stopIcon=${stopIcon};const decorate=()=>{const button=document.getElementById('send-button');if(!button)return;if(button.classList.contains('is-stop')){if(button.dataset.controlState==='running')return;button.dataset.controlState='running';button.innerHTML=stopIcon;button.setAttribute('aria-label','停止生成');button.dataset.tooltip='停止生成';return}if(pauseRequested&&document.querySelector('.chat-thread')){if(button.dataset.controlState==='paused')return;button.dataset.controlState='paused';button.classList.add('is-paused');button.innerHTML=playIcon;button.setAttribute('aria-label','继续生成');button.dataset.tooltip='继续生成'}};document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('#send-button'):null;if(!button)return;if(button.classList.contains('is-stop'))pauseRequested=true;else if(button.classList.contains('is-paused'))pauseRequested=false},true);new MutationObserver(decorate).observe(document.getElementById('page-content')||document.body,{childList:true,subtree:true});decorate()})()`
}

