  return `.template-card{min-height:0;padding:0;overflow:hidden}.template-card .template-cover{position:relative;display:block;width:100%;height:auto;margin:0;aspect-ratio:16/9;padding:0;border:0;background:#f1f3f6;cursor:pointer;overflow:hidden}.template-cover img{display:block;width:100%;height:100%;object-fit:cover}.template-cover:hover img{transform:scale(1.015)}.template-cover img{transition:transform .16s ease}.template-cover-skeleton{width:100%;height:100%;background:linear-gradient(90deg,#f6f6f6 25%,#ededed 38%,#f6f6f6 63%);background-size:400% 100%;animation:template-shimmer 1.25s ease infinite}.template-card-body{padding:14px 15px 15px}.template-card-body h2{margin:0;font-size:15px}.template-card-body p{display:-webkit-box;min-height:36px;margin:8px 0 12px;overflow:hidden;color:#757575;font-size:12px;line-height:1.5;-webkit-line-clamp:2;-webkit-box-orient:vertical}.template-card-footer{display:flex;align-items:center;gap:8px}.template-card-status{color:#858585;font-size:11px}.template-card-action{height:32px;margin-left:auto;padding:0 10px;border:1px solid #dbdbdb;border-radius:7px;background:#fff;color:#252525;font-size:12px;font-weight:600}.template-card-action:hover:not(:disabled){background:#f5f5f5}.template-card-action:disabled{opacity:.55;cursor:wait}.template-card.is-failed .template-card-status{color:#976826}.template-card.is-ready .template-card-status{color:#2d7a58}`
