function templateLibraryResilienceBehavior(): string {
  return `(()=>{const storageKey='dsh-workbench:selected-design-template',content=document.getElementById('page-content'),apiBase=window.__DSH_WORKBENCH_API_BASE__||'/api',api=path=>apiBase+path;let templates=[],catalog={cacheStatus:'cached',syncedAt:'',warning:''},query='';const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;,'"':'&quot;',"'":'&#39;'}[char]));const selected=()=>{try{return JSON.parse(sessionStorage.getItem(storageKey)||'null')}catch{return null}};const setSelected=value=>sessionStorage.setItem(storageKey,JSON.stringify(value));const setStatus=(message,kind='')=>{const node=document.getElementById('template-library-status');if(node){node.className='template-library-status '+kind;node.textContent=message}};function showSelected(){const wrapper=document.querySelector('.composer-wrapper'),value=selected();if(!wrapper)return;document.getElementById('selected-design-template')?.remove();if(!value?.id)return;const chip=document.createElement('div');chip.id='selected-design-template';chip.className='selected-design';chip.innerHTML='<span>已选风格</span><strong>'+escape(value.name||value.id)+'</strong><button type="button" aria-label="移除已选风格">×</button>';chip.querySelector('button')?.addEventListener('click',async()=>{try{const response=await fetch(api('/design-templates/selection'),{method:'DELETE'});if(!response.ok)throw new Error()}catch{alert('暂时无法取消该风格，请稍后重试。');return}sessionStorage.removeItem(storageKey);showSelected()});wrapper.insertBefore(chip,wrapper.querySelector('.composer')||null)}function shell(){content.innerHTML='<section class="template-library"><header class="template-library-header"><div><h1>模板库</h1><p>选择一种设计风格，生成看板时会自动应用。模板内容只在你选择后按需获取。</p></div><div class="template-library-actions"><input id="template-search" class="template-search" type="search" placeholder="搜索风格" value="'+escape(query)+'"><button id="template-sync" class="template-sync" type="button">检查更新</button></div></header><div id="template-library-status" class="template-library-status">正在准备模板目录…</div><p class="template-note">Lieflat 提供真实报告与图表模板；其他设计风格来自 VoltAgent / awesome-design-md。</p><div id="template-library-results"></div></section>'}function skeleton(){shell();document.getElementById('template-library-results').innerHTML='<div class="template-skeleton-grid">'+Array.from({length:8},()=>'<div class="template-skeleton" aria-hidden="true"></div>').join('')+'</div>'}function render(){shell();const needle=query.trim().toLowerCase(),active=selected()?.id,visible=templates.filter(item=>!needle||item.id.includes(needle)||item.name.toLowerCase().includes(needle));const status=catalog.warning||((catalog.cacheStatus==='fresh'?'目录已更新':catalog.cacheStatus==='stale'?'正在使用本地缓存':'已显示本地缓存')+' · '+templates.length+' 个风格');setStatus(status,catalog.cacheStatus==='stale'?'is-stale':'');const result=document.getElementById('template-library-results');result.innerHTML=visible.length?'<div class="template-grid">'+visible.map(item=>'<article class="template-card '+(item.id===active?'is-selected':'')+'"><div class="template-card-head"><span class="template-card-mark">DM</span><h2>'+escape(item.name)+'</h2></div><p>设计风格参考 · DESIGN.md</p><footer><code>'+escape(item.id)+'</code><button type="button" data-design-template="'+escape(item.id)+'">'+(item.id===active?'已选择':'使用此风格')+'</button></footer></article>').join('')+'</div>':'<div class="template-library-empty"><h2>没有找到匹配的风格</h2><p>换一个关键词，或清空搜索后再试。</p><button id="template-clear-search" type="button">清空搜索</button></div>';document.getElementById('template-search')?.addEventListener('input',event=>{query=event.target.value;render()});document.getElementById('template-sync')?.addEventListener('click',()=>load(true));document.getElementById('template-clear-search')?.addEventListener('click',()=>{query='';render()});document.querySelectorAll('[data-design-template]').forEach(button=>button.addEventListener('click',()=>select(button.getAttribute('data-design-template'),button)))}async function load(force){if(!force||!templates.length)skeleton();else setStatus('正在检查更新，继续显示当前目录…');try{const response=await fetch(api(force?'/design-templates/sync':'/design-templates'),force?{method:'POST'}:undefined),data=await response.json();if(!response.ok)throw new Error();templates=Array.isArray(data.templates)?data.templates:[];catalog={cacheStatus:data.cacheStatus||'cached',syncedAt:data.syncedAt||'',warning:data.warning||''};render()}catch{if(templates.length){catalog.warning='暂时无法更新目录，当前可用模板未受影响。';render()}else{shell();setStatus('暂时无法连接模板目录，请检查后重试。','is-error');document.getElementById('template-library-results').innerHTML='<div class="template-library-empty"><h2>模板库暂时不可用</h2><p>这不会影响已有看板；你可以稍后重试。</p><button id="template-retry" type="button">重新加载</button></div>';document.getElementById('template-retry')?.addEventListener('click',()=>load(false))}}}async function select(id,button){if(!id)return;button.disabled=true;button.textContent='正在应用…';try{const response=await fetch(api('/design-templates/selection'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({templateId:id})}),data=await response.json();if(!response.ok)throw new Error();setSelected(data.template);showSelected();button.textContent='已应用';setStatus('已应用“'+(data.template.name||id)+'”，返回会话后直接生成看板即可。');setTimeout(()=>window.location.reload(),350)}catch{button.disabled=false;button.textContent='使用此风格';setStatus('该风格暂时无法加载，请选择其他风格或稍后重试。','is-error')}}document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('.nav-item[data-page="templates"]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===button));load(false)},true);new MutationObserver(showSelected).observe(document.body,{childList:true,subtree:true});showSelected()})()`
}

