/** Kept separate from the long-lived chat state so the template catalog cannot disrupt an active generation. */
function templateLibraryBehavior(): string {
  return `(()=>{const storageKey='dsh-workbench:selected-design-template',content=document.getElementById('page-content');let templates=[];const api=path=>(location.pathname.startsWith('/dsh-workbench')?'/api/dsh-workbench':'/api')+path;const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const chosen=()=>{try{return JSON.parse(sessionStorage.getItem(storageKey)||'null')}catch{return null}};function showSelected(){const wrapper=document.querySelector('.composer-wrapper'),value=chosen();if(!wrapper)return;document.getElementById('selected-design-template')?.remove();if(!value?.id)return;const chip=document.createElement('div');chip.id='selected-design-template';chip.className='selected-design';chip.innerHTML='<span>已选风格</span><strong>'+escape(value.name||value.id)+'</strong><button type="button" aria-label="移除已选风格">×</button>';chip.querySelector('button')?.addEventListener('click',()=>{sessionStorage.removeItem(storageKey);showSelected()});wrapper.insertBefore(chip,wrapper.querySelector('.composer')||null)}function renderLibrary(){const selected=chosen()?.id;const cards=templates.map(item=>'<article class="template-card '+(item.id===selected?'is-selected':'')+'"><div class="template-card-head"><span class="template-card-mark">DM</span><h2>'+escape(item.name)+'</h2></div><p>设计风格参考 · DESIGN.md</p><footer><code>'+escape(item.id)+'</code><button type="button" data-design-template="'+escape(item.id)+'">'+(item.id===selected?'已选择':'使用此风格')+'</button></footer></article>').join('');content.innerHTML='<section class="template-library"><header class="template-library-header"><div><h1>模板库</h1><p>从公开设计系统分析中选择一种视觉风格，用于本次看板生成。资源来自 VoltAgent / awesome-design-md，仅作为风格参考。</p></div><div class="template-library-actions"><button id="template-sync" class="template-sync" type="button">同步更新</button></div></header><p class="template-note">目录首次访问时同步；使用模板时才下载对应 DESIGN.md。MIT 许可，生成时不会使用品牌商标或图片素材。</p><div class="template-grid">'+cards+'</div></section>';document.getElementById('template-sync')?.addEventListener('click',()=>load(true));document.querySelectorAll('[data-design-template]').forEach(button=>button.addEventListener('click',()=>select(button.getAttribute('data-design-template'))))}async function load(force){content.innerHTML='<section class="template-library"><div class="template-empty">正在同步模板目录…</div></section>';try{const response=await fetch(api(force?'/design-templates/sync':'/design-templates'),force?{method:'POST'}:undefined),data=await response.json();if(!response.ok)throw new Error(data.error||'模板目录加载失败');templates=Array.isArray(data.templates)?data.templates:[];renderLibrary()}catch(error){content.innerHTML='<section class="template-library"><div class="template-empty">'+escape(error instanceof Error?error.message:'模板目录加载失败')+'</div></section>'}}async function select(id){if(!id)return;const response=await fetch(api('/design-templates/'+encodeURIComponent(id))),data=await response.json();if(!response.ok){alert(data.error||'模板加载失败');return}sessionStorage.setItem(storageKey,JSON.stringify(data.template));window.location.reload()}document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('.nav-item[data-page="templates"]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===button));load(false)},true);const originalFetch=window.fetch.bind(window);window.fetch=(input,init)=>{const raw=typeof input==='string'?input:input instanceof URL?input.toString():input.url||'';const path=new URL(raw,location.origin).pathname;if((init?.method||'GET').toUpperCase()==='POST'&&path.endsWith('/runs')&&typeof init?.body==='string'){const value=chosen();if(value?.id){const body=JSON.parse(init.body);body.designTemplateId=value.id;init={...init,body:JSON.stringify(body)}}}return originalFetch(input,init)};new MutationObserver(showSelected).observe(document.body,{childList:true,subtree:true});showSelected()})()`
}

function templateLibraryBehaviorLegacy(): string {
  return `(()=>{const key='dsh-workbench:selected-design-template',content=document.getElementById('page-content');let templates=[];const api=path=>(location.pathname.startsWith('/dsh-workbench')?'/api/dsh-workbench':'/api')+path;const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const selected=()=>{try{return JSON.parse(sessionStorage.getItem(key)||'null')}catch{return null}};const setSelected=value=>sessionStorage.setItem(key,JSON.stringify(value));const clearSelected=()=>sessionStorage.removeItem(key);function selectionChip(){const value=selected(),wrapper=document.querySelector('.composer-wrapper');if(!wrapper)return;document.getElementById('selected-design-template')?.remove();if(!value?.id)return;const chip=document.createElement('div');chip.id='selected-design-template';chip.className='selected-design';chip.innerHTML='<span>已选风格</span><strong>'+escape(value.name||value.id)+'</strong><button type="button" aria-label="移除已选风格">×</button>';chip.querySelector('button')?.addEventListener('click',()=>{clearSelected();selectionChip()});wrapper.insertBefore(chip,wrapper.querySelector('.composer')||null)}function page(){const query=document.getElementById('template-search')?.value||'';const needle=query.trim().toLowerCase();const chosen=selected()?.id;const visible=templates.filter(item=>!needle||item.name.toLowerCase().includes(needle)||item.id.toLowerCase().includes(needle));const cards=visible.map(item=>'<article class="template-card '+(item.id===chosen?'is-selected':'')+'"><div class="template-card-head"><span class="template-card-mark">DM</span><h2>'+escape(item.name)+'</h2></div><p>设计风格参考 · DESIGN.md</p><footer><code>'+escape(item.id)+'</code><button type="button" data-use-template="'+escape(item.id)+'">'+(item.id===chosen?'已选择':'使用此风格')+'</button></footer></article>').join('');content.innerHTML='<section class="template-library"><header class="template-library-header"><div><h1>模板库</h1><p>从公开设计系统分析中选择一种视觉风格，用于本次看板生成。资源来自 VoltAgent / awesome-design-md，仅作为风格参考。</p></div><div class="template-library-actions"><input id="template-search" class="template-search" type="search" placeholder="搜索风格" value="'+escape(query)+'"><button id="template-sync" class="template-sync" type="button">同步更新</button></div></header><p class="template-note">已按需同步目录；点击“使用此风格”时才会下载对应 DESIGN.md。MIT 许可，生成时不会使用品牌商标或图片素材。</p><div id="template-status" class="template-empty">'+(templates.length?cards:'正在加载模板目录…')+'</div></section>';const host=document.getElementById('template-status');if(templates.length){host.className='template-grid';host.innerHTML=cards}document.getElementById('template-search')?.addEventListener('input',page);document.getElementById('template-sync')?.addEventListener('click',()=>load(true));document.querySelectorAll('[data-use-template]').forEach(button=>button.addEventListener('click',()=>use(button.getAttribute('data-use-template'))))}async function load(force){content.innerHTML='<section class="template-library"><div class="template-empty">正在同步模板目录…</div></section>';try{const response=await fetch(api(force?'/design-templates/sync':'/design-templates'),force?{method:'POST'}:undefined),data=await response.json();if(!response.ok)throw new Error(data.error||'模板目录加载失败');templates=Array.isArray(data.templates)?data.templates:[];page()}catch(error){content.innerHTML='<section class="template-library"><div class="template-empty">'+escape(error instanceof Error?error.message:'模板目录加载失败')+'</div></section>'}}async function use(id){if(!id)return;const response=await fetch(api('/design-templates/'+encodeURIComponent(id))),data=await response.json();if(!response.ok){alert(data.error||'模板加载失败');return}setSelected(data.template);window.location.reload()}document.addEventListener('click',event=>{const target=event.target instanceof Element?event.target.closest('.nav-item[data-page="templates"]'):null;if(!target)return;event.preventDefault();event.stopImmediatePropagation();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===target));load(false)},true);const originalFetch=window.fetch.bind(window);window.fetch=(input,init)=>{const url=typeof input==='string'?input:input instanceof URL?input.toString():input.url||'';if((init?.method||'GET').toUpperCase()==='POST'&&/\\/runs$/.test(new URL(url,location.origin).pathname)&&typeof init?.body==='string'){try{const body=JSON.parse(init.body),value=selected();if(value?.id){body.designTemplateId=value.id;init={...init,body:JSON.stringify(body)}}catch{}}return originalFetch(input,init)};new MutationObserver(selectionChip).observe(document.body,{childList:true,subtree:true});selectionChip()})()`
}

