function shell(): string {
  return `<main class="workbench" id="app"><aside class="sidebar" aria-label="看板工作台导航"><header class="brand-row"><span class="brand-icon">${workbenchNavigationIcon()}</span><strong>看板工作台</strong><div class="brand-actions"><button id="search-button" class="icon-button" aria-label="搜索" data-tooltip="搜索">${icon('search')}</button><button id="collapse-button" class="icon-button" aria-label="收起侧栏" data-tooltip="收起侧栏">${icon('collapse')}</button></div></header><div class="search-popover" id="search-popover" hidden><input id="search-input" type="search" placeholder="搜索看板"></div><nav class="nav-list" aria-label="主导航"><button class="nav-item active" data-page="new" data-tooltip="新建看板">${icon('new')}<span>新建看板</span></button><button class="nav-item" data-page="boards" data-tooltip="我的看板">${icon('folder')}<span>我的看板</span></button><button class="nav-item" data-page="subscriptions" data-tooltip="智能订阅">${icon('bell')}<span>智能订阅</span></button><button class="nav-item template-nav-item" data-page="templates" data-template-library type="button" data-tooltip="模板库" aria-label="模板库">${icon('library')}<span>模板库</span></button></nav></aside><section class="content" aria-live="polite"><div id="page-content"></div></section></main>`
}

/** The iframe cannot assume a host icon package; keep the supplied neutral line icon set self-contained. */
function icon(name: string): string {
  if (name === 'search') return '<img class="search-image" src="data:image/png;base64," alt="" aria-hidden="true">'
  if (name === 'dashboard') return '<img class="dashboard-image" src="data:image/png;base64," alt="" aria-hidden="true">'
  if (name === 'new') return '<img class="new-image" src="data:image/png;base64," alt="" aria-hidden="true">'
  if (name === 'collapse') return '<img class="collapse-image" src="data:image/png;base64," alt="" aria-hidden="true">'
  const paths: Record<string, string> = {
    search: '<circle cx="10.5" cy="10.5" r="5.5"/><path d="m15 15 4 4"/>', collapse: '<path d="M16 5 9 12l7 7"/><path d="M7 5v14"/>', new: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 3v7h7"/><path d="M8 15h8M12 11v8"/>', folder: '<path d="M3 7.5a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>', bell: '<path d="M18 9a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>', user: '<circle cx="12" cy="8" r="4"/><path d="M4 21c.7-4 3.3-6 8-6s7.3 2 8 6"/>', chevron: '<path d="m8 10 4 4"/>', chevronDown: '<path d="m6 9 6 6 6-6"/>', plus: '<path d="M12 5v14M5 12h14"/>', agent: '<circle cx="12" cy="8" r="3.5"/><path d="M5 20v-2.2a4.8 4.8 0 0 1 4.8-4.8h4.4a4.8 4.8 0 0 1 4.8 4.8V20"/><path d="M3.5 11.5V9.8M20.5 11.5V9.8"/>', send: '<path d="m21 3-7.3 18-3.7-7.3L3 10.3z"/><path d="m10 14 4.5-4.5"/>', play: '<path d="M8.5 6.5 18 12l-9.5 5.5z" fill="currentColor" stroke="none"/>', stop: '<rect x="7" y="7" width="10" height="10" rx="1.5" fill="currentColor" stroke="none"/>', close: '<path d="m6 6 12 12M18 6 6 18"/>', paperclip: '<path d="m20.5 11.5-7.7 7.7a5 5 0 0 1-7.1-7.1l8.1-8.1a3.4 3.4 0 1 1 4.8 4.8l-8.1 8.1a1.8 1.8 0 0 1-2.6-2.6l7.4-7.4"/>', library: '<path d="M4 5.5 8.5 4 13 5.5 17.5 4 22 5.5v13l-4.5-1.5-4.5 1.5-4.5-1.5L4 18.5z"/><path d="M8.5 4v13M13 5.5v13M17.5 4v13"/>', document: '<path d="M5 3h9l5 5v13H5z"/><path d="M14 3v6h5M8 14h8M8 18h5"/>'
  }
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name] ?? ''}</svg>`
}

