function behavior(): string {
  return `const content=document.getElementById('page-content'),sidebar=document.querySelector('.sidebar'),workbench=document.querySelector('.workbench');if(new URLSearchParams(location.search).has('embedded'))workbench.classList.add('host-embedded');const historyKey='dsh-workbench:build-history';const loadHistory=()=>{try{const saved=JSON.parse(localStorage.getItem(historyKey)||'[]');return Array.isArray(saved)?saved:[]}catch{return []}};const saveHistory=items=>localStorage.setItem(historyKey,JSON.stringify(items));const state={page:'new',file:null,upload:null,pendingPrompt:'',sending:false,attachOpen:false,requestId:null,sessionId:null,runState:'idle',activity:'',timeline:[],history:loadHistory(),stream:null,streamState:'idle',agent:'通用数据智能体',draft:'',timers:[],runId:null,abortController:null};const icons={plus:'${icon('plus')}',send:'${icon('send')}',close:'${icon('close')}',paperclip:'${icon('paperclip')}',library:'${icon('library')}',document:'${icon('document')}',agent:'${icon('agent')}',chevron:'${icon('chevron')}',chevronDown:'${icon('chevronDown')}'};const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function completedStream(question){return {question:question||'已恢复看板搭建任务',name:true,planText:'',tools:[],findings:[],lists:[],artifacts:[]}}function persistActiveHistory(){const index=state.history.findIndex(item=>item.sessionId===state.sessionId);if(index<0)return;state.history[index]={...state.history[index],updatedAt:Date.now(),activityAt:Date.now(),timeline:state.timeline,activity:state.activity,runState:state.runState,stream:state.stream,streamState:state.streamState};saveHistory(state.history)}function restoreHistory(sessionId){const item=state.history.find(record=>record.sessionId===sessionId);if(!item)return;state.requestId=crypto.randomUUID();state.sessionId=item.sessionId;state.timeline=Array.isArray(item.timeline)?item.timeline:[];state.activity=item.activity||'已恢复看板搭建过程';state.runState=item.runState||'complete';state.stream=item.stream||completedStream(item.title);if(state.stream){state.stream.planText='';state.stream.findings=[];state.stream.lists=[]}state.streamState=item.streamState||'completed';state.sending=false;state.page='new';state.attachOpen=false;render();renderHistory();if(window.parent!==window)window.parent.postMessage({source:'dsh-workbench',kind:'load-session',requestId:state.requestId,sessionId:item.sessionId},location.origin)}function ensureHistory(){let host=document.getElementById('history-list');if(!host){sidebar.insertAdjacentHTML('beforeend','<section class="sidebar-history" aria-label="看板搭建历史"><div id="history-list" class="history-list"></div></section>');host=document.getElementById('history-list')}return host}function renderHistory(){const host=ensureHistory();if(!host)return;host.innerHTML=state.history.map(item=>'<button class="history-item" type="button" data-session-id="'+escapeHtml(item.sessionId)+'"><strong>'+escapeHtml(item.title)+'</strong><span>'+new Date(item.createdAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+'</span></button>').join('');host.querySelectorAll('.history-item').forEach(button=>button.addEventListener('click',()=>restoreHistory(button.dataset.sessionId)))}function attachmentPopover(){return '<div class="attachment-popover" id="attachment-popover"><button class="attachment-item" id="attach-local">'+icons.paperclip+'<strong>上传本地文件</strong><span>数据集 / 知识附件</span></button><button class="attachment-item" id="attach-library">'+icons.library+'<strong>从资料库中添加</strong><span>浏览和搜索工作空间文件</span></button><button class="attachment-item" id="attach-doc">'+icons.document+'<strong>粘贴飞书云文档添加</strong><span>粘贴飞书文档链接</span></button></div>'}
function agentSelector(){return '<div class="agent-select"><button id="agent-toggle" type="button" aria-expanded="false">'+icons.agent+'<span>'+escapeHtml(state.agent)+'</span></button><div class="agent-menu" id="agent-menu" hidden><button type="button" data-agent="通用数据智能体">通用数据智能体</button><button type="button" data-agent="经营分析智能体">经营分析智能体</button><button type="button" data-agent="销售分析智能体">销售分析智能体</button></div></div>'}function toolLine(icon,text,status){return '<div class="tool-line" data-status="'+status+'">'+icon+'<span>'+escapeHtml(text)+'</span><em class="tool-state">'+(status==='running'?'执行中':status==='failed'?'失败':'已完成')+'</em></div>'}function assistantParagraphs(text){return String(text||'').split(String.fromCharCode(10)).map(part=>part.trim()).filter(Boolean).map(part=>'<p class="agent-block agent-output">'+escapeHtml(part)+'</p>').join('')}function agentAnswer(){const s=state.stream;if(!s)return '';let html='<article class="agent-message">';if(s.name)html+='<div class="agent-name">'+icons.agent+'<span>'+escapeHtml(state.agent)+'</span></div>';if(s.planText)html+='<p class="agent-block agent-plan">'+escapeHtml(s.planText)+(state.streamState==='planning'?'<i class="stream-caret"></i>':'')+'</p>';if(s.output)html+=assistantParagraphs(s.output);for(const item of s.tools||[])html+=toolLine(item.type==='artifact'?icons.document:icons.library,item.title,item.status);for(const finding of s.findings||[])html+='<p class="agent-block agent-finding">'+escapeHtml(finding)+'</p>';for(const list of s.lists||[])html+='<div class="agent-block agent-result"><p>'+escapeHtml(list.intro)+'</p><ul>'+list.items.map(item=>'<li>'+escapeHtml(item)+'</li>').join('')+'</ul></div>';for(const artifact of s.artifacts||[])html+='<p class="agent-block agent-artifact"><a href="'+escapeHtml(artifact.previewUrl)+'" target="_blank" rel="noopener">'+escapeHtml(artifact.title)+'</a></p>';if(s.error)html+='<p class="agent-block agent-error">'+escapeHtml(s.error)+'</p>';if(state.sending)html+='<p class="agent-block agent-next">'+escapeHtml(state.activity||'正在执行数据分析。')+'<i class="stream-caret"></i></p>';return html+'</article>'}
function newPage(){const hasStream=Boolean(state.stream);const thread=hasStream?'<div class="chat-thread"><div class="user-message">'+escapeHtml(state.stream.question)+'</div>'+agentAnswer()+'</div>':'<div class="chat-empty"><h1>从数据到正式看板，按受控流程完成搭建</h1><p>上传数据或选择数据资产，确认指标口径与看板结构；AI 协助识别、推荐和校验，全程保留版本与发布记录。</p></div>';const file=state.file;const composer='<div class="composer-wrapper chat-composer '+(hasStream?'':'task-launch-composer')+'">'+(state.attachOpen?attachmentPopover():'')+'<div class="composer '+(file?'has-file':'')+'" id="composer"><textarea id="prompt" class="prompt" aria-label="看板需求" placeholder="继续补充要求或调整分析范围">'+escapeHtml(state.draft)+'</textarea>'+(!file?'':'<div class="attachment"><strong>'+escapeHtml(file.name)+'</strong><button id="remove-file" aria-label="移除文件" data-tooltip="移除文件">'+icons.close+'</button></div>')+'<div class="composer-footer"><input id="file-input" type="file" accept=".csv,text/csv" hidden><button class="round-button" id="upload-button" aria-label="添加附件" data-tooltip="添加附件" aria-expanded="'+(state.attachOpen?'true':'false')+'">'+icons.plus+'</button>'+agentSelector()+'<button class="send-button '+(state.sending?'is-stop':'')+'" id="send-button" aria-label="'+(state.sending?'停止':'发送')+'" data-tooltip="'+(state.sending?'停止':'发送')+'" '+((!state.sending&&!state.draft.trim()&&!file)?'disabled':'')+'>'+((state.sending?'停止':icons.send))+'</button></div></div></div>';return '<section class="new-page"><div class="chat-layout">'+(hasStream?thread:'<div class="task-launch">'+thread+composer+'</div>')+'</div>'+(hasStream?composer:'')+'</section>'}
const initialPage=new URLSearchParams(location.search).get('page');if(initialPage==='new'||initialPage==='boards'||initialPage==='subscriptions')state.page=initialPage;document.addEventListener('click',event=>{if(!location.pathname.endsWith('/templates'))return;const button=event.target instanceof Element?event.target.closest('.nav-item[data-page]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();location.assign('/dsh-workbench?page='+encodeURIComponent(button.dataset.page||'new'))},true);const templateApi=location.pathname.startsWith('/dsh-workbench')?'/api/dsh-workbench':'/api';function templatePage(){return '<section class="template-library"><header class="template-library-header"><div><h1>模板库</h1><p>选择设计风格后，后续生成的看板会自动应用该风格。</p></div></header><div id="template-library-status" class="template-library-status">正在加载模板目录…</div><p class="template-note">Lieflat 提供真实报告与图表模板；其他设计风格来自 VoltAgent / awesome-design-md。</p><div id="template-library-results" class="template-skeleton-grid">'+Array.from({length:8},()=>'<div class="template-skeleton" aria-hidden="true"></div>').join('')+'</div></section>'}async function chooseDesignTemplate(id){const response=await fetch(templateApi+'/design-templates/selection',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({templateId:id})}),data=await response.json();if(!response.ok)throw new Error(data.error||'模板加载失败');sessionStorage.setItem('dsh-workbench:selected-design-template',JSON.stringify(data.template));const status=document.getElementById('template-library-status');if(status)status.textContent='已应用“'+(data.template.name||id)+'”，返回会话后直接生成看板即可。'}async function loadTemplatePage(){const host=document.getElementById('template-library-results'),status=document.getElementById('template-library-status');if(!host||!status)return;try{const response=await fetch(templateApi+'/design-templates'),data=await response.json();if(!response.ok)throw new Error(data.error||'模板目录加载失败');const templates=Array.isArray(data.templates)?data.templates:[];status.textContent=(data.warning||'已加载 '+templates.length+' 个风格');host.className='template-grid';host.innerHTML=templates.map(item=>'<article class="template-card"><div class="template-card-head"><span class="template-card-mark">DM</span><h2>'+escapeHtml(item.name)+'</h2></div><p>设计风格参考 · DESIGN.md</p><footer><code>'+escapeHtml(item.id)+'</code><button type="button" data-design-template="'+escapeHtml(item.id)+'">使用此风格</button></footer></article>').join('');host.querySelectorAll('[data-design-template]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;button.textContent='正在应用…';try{await chooseDesignTemplate(button.dataset.designTemplate);button.textContent='已应用'}catch(error){button.disabled=false;button.textContent='重试';status.textContent=error instanceof Error?error.message:'模板加载失败'}}))}catch(error){host.className='template-library-empty';host.innerHTML='<h2>模板库暂时不可用</h2><p>请稍后刷新重试。</p>';status.className='template-library-status is-error';status.textContent=error instanceof Error?error.message:'模板目录加载失败'}}
function simplePage(){const copy=state.page==='boards'?['我的看板','你创建的看板会出现在这里。']:['智能订阅','为关键数据设置持续关注。'];return '<section class="simple-page"><h1>'+copy[0]+'</h1><p>'+copy[1]+'</p><div class="empty-note">暂无内容</div></section>'}
function decorateHomeHero(){const title=content.querySelector('.task-launch .chat-empty h1');if(!title)return;const row=document.createElement('div'),logo=document.createElement('img');row.className='hero-title-row';logo.className='hero-title-logo';logo.src=(location.pathname.startsWith('/dsh-workbench')?'/dsh-workbench':'')+'/'+'assets/data-agent-logo-black.png';logo.alt='';logo.setAttribute('aria-hidden','true');title.before(row);row.append(logo,title)}
function render(){const isTemplatePage=location.pathname.endsWith('/templates');content.innerHTML=isTemplatePage?templatePage():(state.page==='new'?newPage():simplePage());if(!isTemplatePage&&state.page==='new')decorateHomeHero();if(isTemplatePage)void loadTemplatePage();bind()}
function updateSend(){const prompt=document.getElementById('prompt');const send=document.getElementById('send-button');if(send)send.disabled=!state.sending&&!(prompt?.value.trim()||state.file)}
function choose(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.csv'))return alert('请选择 CSV 文件');if(file.size>20*1024*1024)return alert('文件不能超过 20 MB');state.file=file;render()}
function clearStreamTimers(){state.timers.forEach(timer=>clearTimeout(timer));state.timers=[]}function refreshStream(){if(state.sessionId)persistActiveHistory();render();if(state.followOutput!==false)requestAnimationFrame(()=>window.scrollTo({top:document.documentElement.scrollHeight,behavior:'smooth'}))}function beginLiveStream(question){state.streamState='planning';state.sending=true;state.stream={live:true,question,name:true,planText:'',tools:[],findings:[],lists:[],artifacts:[]};refreshStream()}async function stopStream(){const runId=state.runId;state.abortController?.abort();state.abortController=null;state.sending=false;state.streamState='stopped';if(state.stream)state.stream.stopped=true;refreshStream();if(runId)try{await fetch('/api/runs/'+encodeURIComponent(runId)+'/cancel',{method:'POST'})}catch{}}function toolFor(id,title,status){const tools=state.stream.tools;let item=tools.find(entry=>entry.id===id);if(!item){item={id,title,status};tools.push(item)}item.title=title;item.status=status}function applyRunEvent(event){if(!state.stream)return;const data=event.data||{};if(event.type==='run.started'){state.runId=event.runId;state.activity='正在读取数据文件';state.stream.name=true}else if(event.type==='text.delta'){state.stream.planText+=(data.delta||'')}else if(event.type==='tool.started'||event.type==='tool.progress'){state.streamState='reading';state.activity=data.title||'正在执行数据分析';toolFor(data.toolCallId,data.title||'执行分析步骤','running')}else if(event.type==='tool.completed'){state.activity=data.title||'分析步骤完成';toolFor(data.toolCallId,data.title||'分析步骤完成','completed')}else if(event.type==='finding.created'){state.stream.findings.push(data.text||'')}else if(event.type==='list.created'){state.stream.lists.push({intro:data.intro||'',items:Array.isArray(data.items)?data.items:[]})}else if(event.type==='artifact.created'){state.stream.artifacts.push({title:data.title||'查看生成的看板',previewUrl:data.previewUrl||'#'});state.activity='看板草稿已生成'}else if(event.type==='run.completed'){state.sending=false;state.streamState='completed';state.activity='已完成'}else if(event.type==='run.stopped'){state.sending=false;state.streamState='stopped';state.activity='已停止'}else if(event.type==='run.error'){state.sending=false;state.streamState='error';state.stream.error=data.message||'看板生成失败'}refreshStream()}async function consumeRun(response){if(!response.body)throw new Error('浏览器不支持流式响应');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});const entries=buffer.split(String.fromCharCode(10)+String.fromCharCode(10));buffer=entries.pop()||'';for(const entry of entries){const eventName=entry.split(String.fromCharCode(10)).find(line=>line.startsWith('event:'))?.slice(6).trim();const payload=entry.split(String.fromCharCode(10)).find(line=>line.startsWith('data:'))?.slice(5).trim();if(eventName&&payload)applyRunEvent({type:eventName,data:JSON.parse(payload).data,runId:JSON.parse(payload).runId})}}}async function send(){if(state.sending){await stopStream();return}const prompt=document.getElementById('prompt')?.value.trim()||state.draft.trim();if(!prompt&&!state.file)return;if(!state.file){alert('请先上传 CSV 文件，再开始分析。');return}state.draft=prompt||'请根据上传数据生成一张看板。';beginLiveStream(state.draft);state.abortController=new AbortController();try{const csv=await state.file.text(),uploadResponse=await fetch('/api/uploads',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({csv,fileName:state.file.name}),signal:state.abortController.signal}),upload=await uploadResponse.json();if(!uploadResponse.ok)throw new Error(upload.error||'上传失败');const response=await fetch('/api/runs',{method:'POST',headers:{'content-type':'application/json',accept:'text/event-stream'},body:JSON.stringify({uploadId:upload.uploadId,intent:state.draft,agent:state.agent}),signal:state.abortController.signal});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||'启动分析失败')}await consumeRun(response)}catch(error){if(error?.name!=='AbortError'){state.sending=false;state.streamState='error';if(state.stream)state.stream.error=error instanceof Error?error.message:'数据分析启动失败';refreshStream()}}finally{state.abortController=null}}
function closeSearch(){const popover=document.getElementById('search-popover');if(popover)popover.hidden=true}function bind(){document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{state.page=button.dataset.page;state.attachOpen=false;closeSearch();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===button));render()}));const input=document.getElementById('file-input');document.getElementById('upload-button')?.addEventListener('click',()=>{state.attachOpen=!state.attachOpen;closeSearch();render()});document.getElementById('attach-local')?.addEventListener('click',()=>input?.click());document.getElementById('attach-library')?.addEventListener('click',()=>alert('资料库附件将在下一阶段接入。'));document.getElementById('attach-doc')?.addEventListener('click',()=>alert('飞书文档链接附件将在下一阶段接入。'));input?.addEventListener('change',()=>{state.attachOpen=false;choose(input.files?.[0])});document.getElementById('remove-file')?.addEventListener('click',()=>{state.file=null;render()});const prompt=document.getElementById('prompt');prompt?.addEventListener('input',event=>{state.draft=event.target.value;updateSend()});const composer=document.getElementById('composer');composer?.addEventListener('dragover',event=>{event.preventDefault();composer.style.borderColor='#aaa'});composer?.addEventListener('dragleave',()=>composer.style.borderColor='');composer?.addEventListener('drop',event=>{event.preventDefault();composer.style.borderColor='';state.attachOpen=false;choose(event.dataTransfer?.files?.[0])});document.getElementById('send-button')?.addEventListener('click',()=>{if(location.pathname.startsWith('/dsh-workbench')&&typeof window.startHostAgentRun==='function')void window.startHostAgentRun();else void send()});document.getElementById('agent-toggle')?.addEventListener('click',()=>{const menu=document.getElementById('agent-menu');menu.hidden=!menu.hidden;document.getElementById('agent-toggle').setAttribute('aria-expanded',String(!menu.hidden))});document.querySelectorAll('[data-agent]').forEach(button=>button.addEventListener('click',()=>{state.agent=button.dataset.agent;render()}));if(!state.scrollBound){state.scrollBound=true;window.addEventListener('scroll',()=>{state.followOutput=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-72},{passive:true})};document.getElementById('open-session')?.addEventListener('click',()=>{if(state.sessionId)window.parent.postMessage({source:'dsh-workbench',kind:'open-session',requestId:state.requestId,sessionId:state.sessionId},location.origin)})}
function applyBackendUpdate(data,completed){if(!state.stream||!state.stream.live)return;state.stream.name=true;const timeline=Array.isArray(data.timeline)?data.timeline:[];state.stream.tools=timeline.filter(item=>item&&['tool','artifact','error'].includes(item.type)).map(item=>({title:item.title||'执行数据分析步骤',status:item.status||'running',type:item.type}));if(typeof data.assistantText==='string'&&data.assistantText.trim())state.stream.output=data.assistantText.trim();if(completed){state.sending=false;state.streamState='completed'}else{state.sending=true;state.streamState=state.stream.tools.some(item=>item.status==='running')?'reading':'responding'}}function updateConversation(){window.addEventListener('message',event=>{const data=event.data||{};if(event.origin!==location.origin||data.source!=='dsh-workbench'||data.requestId!==state.requestId)return;if(data.kind==='history-loaded'){state.sessionId=data.sessionId||state.sessionId;state.runState=data.running?'running':'complete';state.timeline=Array.isArray(data.timeline)&&data.timeline.length?data.timeline:state.timeline;state.activity=typeof data.activity==='string'?data.activity:(data.running?'正在继续分析':'已恢复看板搭建过程');if(Array.isArray(data.timeline)&&data.timeline.length){state.stream={live:true,question:state.stream?.question||'已恢复看板搭建任务',name:true,planText:'已恢复 DSH 会话，正在同步真实执行记录。',tools:[],output:''};applyBackendUpdate(data,!data.running)}persistActiveHistory();render();renderHistory();return}if(data.kind==='history-load-failed'){state.activity=typeof data.message==='string'?data.message:state.activity;refreshStream();return}if(data.kind==='agent-started'){state.sessionId=data.sessionId;state.runState='running';const historyTitle=state.file?.name?.replace(/\.csv$/i,'')||'数据看板';const previousHistory=state.history.find(item=>item.sessionId===data.sessionId);state.history=[{...previousHistory,sessionId:data.sessionId,title:previousHistory?.title||'生成看板：'+historyTitle,createdAt:previousHistory?.createdAt||Date.now(),updatedAt:Date.now(),activityAt:Date.now(),timeline:state.timeline,activity:state.activity,runState:state.runState,stream:state.stream,streamState:state.streamState},...state.history.filter(item=>item.sessionId!==data.sessionId)];saveHistory(state.history);refreshStream();renderHistory();return}if(data.kind==='agent-update'||data.kind==='agent-complete'){const complete=data.kind==='agent-complete';state.runState=complete?'complete':'running';state.timeline=[...state.timeline.filter(item=>item.id==='user'||item.id==='analysis:start'),...(Array.isArray(data.timeline)?data.timeline:[])];state.activity=typeof data.activity==='string'?data.activity:state.activity;const start=state.timeline.find(item=>item.id==='analysis:start');if(start)start.status=complete?'completed':'running';applyBackendUpdate(data,complete);refreshStream();return}if(data.kind==='agent-stopped'){state.sending=false;state.streamState='stopped';state.activity='已停止 DSH 数据分析任务';if(state.stream)state.stream.stopped=true;refreshStream();return}if(data.kind==='agent-stop-failed'){state.activity=typeof data.message==='string'?data.message:'停止任务失败';refreshStream();return}if(data.kind==='agent-failed'){state.sending=false;state.runState='failed';state.streamState='error';state.timeline=[...state.timeline.filter(item=>item.id!=='analysis:start'),{id:'error',type:'error',status:'failed',title:'任务启动失败',summary:typeof data.message==='string'?data.message:'无法启动数据智能体'}];if(state.stream)state.stream.error=typeof data.message==='string'?data.message:'无法启动数据智能体';refreshStream()}});document.getElementById('search-button')?.addEventListener('click',()=>{const popover=document.getElementById('search-popover'),opening=popover.hidden;state.attachOpen=false;render();popover.hidden=!opening;if(opening)setTimeout(()=>document.getElementById('search-input')?.focus(),0)});document.getElementById('collapse-button')?.addEventListener('click',()=>sidebar.classList.toggle('collapsed'));document.getElementById('return-session')?.addEventListener('click',()=>window.parent.postMessage({source:'dsh-workbench',kind:'close-workbench'},location.origin));document.addEventListener('keydown',event=>{if(event.key==='Escape'){const hasPopover=state.attachOpen||!document.getElementById('search-popover').hidden;if(hasPopover){state.attachOpen=false;closeSearch();render();return}window.parent.postMessage({source:'dsh-workbench',kind:'close-workbench'},location.origin)}});render();renderHistory()}updateConversation();`
}

export function renderLocalWorkbenchPage(options: { apiBase?: string; initialPage?: 'new' | 'templates' } = {}): string {
  return applyHistoryManagement(applyConversationHandoff(renderLocalWorkbenchPageBase(options))
    .replace('</style>', `${myDashboardsSidebarStyles()}${myDashboardsToolbarPlacementStyles()}${dashboardCardLayoutStyles()}${dashboardGridStyles()}${conversationHandoffStyles()}.composer-wrapper.chat-composer:not(.task-launch-composer) .composer.has-file{height:130px}</style>`)
    .replace("fetch('/api/dashboards')", "fetch('/api/dashboards?includeDrafts=true')")
    .replace('</body>', `<script>${navigationRouteGuardBehavior()}</script><script>${forceMyDashboardsRecoveryBehavior()}</script><script>${dashboardCardLayoutRecoveryBehavior()}</script><script>${dashboardPaginationBehavior()}</script><script>${dashboardSinglePageIndicatorBehavior()}</script></body>`))
}
